<?php include 'connect.php'; \ = "SELECT d.dptID, d.dptName, (SELECT COUNT(p.policyID) FROM policytbl p JOIN accdatatbl a ON p.policyAuthor = a.accID JOIN empperdeptbl e ON a.accID = e.accID JOIN dorgtbl d_child ON e.dptID = d_child.dptID WHERE (d_child.dptID = d.dptID OR d_child.dptParentID = d.dptID) AND p.policyStatusID IN (4, 5)) AS policiesApproved, (SELECT COUNT(p.policyID) FROM policytbl p JOIN accdatatbl a ON p.policyAuthor = a.accID JOIN empperdeptbl e ON a.accID = e.accID JOIN dorgtbl d_child ON e.dptID = d_child.dptID WHERE (d_child.dptID = d.dptID OR d_child.dptParentID = d.dptID)) AS totalPoliciesSubmitted FROM dorgtbl d WHERE d.dptParentID IS NULL"; \ = \->query(\); if (\) while(\=\->fetch_assoc()) print_r(\); else echo \->error; ?>
